select s.bs_id, s.material_id, s.warehouse_id, s.location_id, s.batch_id, s.qty, s.qty_locked, s.version, s.create_by, s.create_time, s.update_by, s.update_time, b.batch_code, wh.warehouse_name, loc.warehouse_name as location_name, mm.material_code as stock_material_code from food_batch_stock s left join food_batch b on b.batch_id = s.batch_id left join wms_warehouse wh on wh.warehouse_id = s.warehouse_id left join wms_warehouse loc on loc.warehouse_id = s.location_id left join wms_material mm on mm.material_id = s.material_id
AND s.material_id = #{materialId} AND s.warehouse_id = #{warehouseId} AND s.location_id = #{locationId} AND s.batch_id = #{batchId}
order by s.bs_id

select s.*, b.batch_code from food_batch_stock s
left join food_batch b on b.batch_id = s.batch_id
where s.batch_id = #{batchId} and s.warehouse_id = #{warehouseId} and s.location_id = #{locationId}
